#!/usr/bin/env node
// Nightly packages wear the "Moonlit pond" icon from rhwp/assets/logo/nightly/
// (generated by scripts/generate-nightly-icon.py). package-desktop runs this
// after it sets the package version and before it builds Studio and packages,
// so the swap follows the version itself: any `-nightly.` version gets the
// nightly icon, and release versions keep the release icon untouched.
import { copyFileSync, existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = path.resolve(fileURLToPath(new URL('..', import.meta.url)));

export const NIGHTLY_ICON_DIR = 'rhwp/assets/logo/nightly';

// Release icon path → nightly replacement in NIGHTLY_ICON_DIR.
export const NIGHTLY_ICON_FILES = {
  'build/icon.icns': 'icon.icns',
  'build/icon.ico': 'icon.ico',
  'rhwp/assets/logo/logo-512.png': 'icon-512.png',
  'rhwp/rhwp-studio/public/favicon.ico': 'icon.ico',
  'rhwp/rhwp-studio/public/icons/icon-128.png': 'icon-128.png',
  'rhwp/rhwp-studio/public/icons/icon-192.png': 'icon-192.png',
  'rhwp/rhwp-studio/public/icons/icon-256.png': 'icon-256.png',
  'rhwp/rhwp-studio/public/icons/icon-512.png': 'icon-512.png',
};

// Nightly versions are `<release>-nightly.<UTC yyyymmdd>.<short sha>`.
export function isNightlyVersion(version) {
  return /^\d+\.\d+\.\d+-nightly(?:\.|$)/.test(String(version ?? ''));
}

function packageVersion(root) {
  return JSON.parse(readFileSync(path.join(root, 'package.json'), 'utf8')).version;
}

export function applyNightlyIcon({ root = ROOT, version = packageVersion(root) } = {}) {
  if (!isNightlyVersion(version)) return [];
  const pairs = Object.entries(NIGHTLY_ICON_FILES).map(([dest, source]) => [
    path.join(root, dest),
    path.join(root, NIGHTLY_ICON_DIR, source),
  ]);
  // Check every source first so a missing file never leaves a half-swapped icon set.
  for (const [, source] of pairs) {
    if (!existsSync(source)) throw new Error(`Nightly icon is missing: ${source}`);
  }
  for (const [dest, source] of pairs) copyFileSync(source, dest);
  return Object.keys(NIGHTLY_ICON_FILES);
}

// The packaged Studio favicon shows which icon set the package was built with.
export function assertPackagedIcon({ root = ROOT, version, favicon }) {
  const nightlyIcon = readFileSync(path.join(root, NIGHTLY_ICON_DIR, NIGHTLY_ICON_FILES['rhwp/rhwp-studio/public/favicon.ico']));
  const wearsNightly = Buffer.from(favicon).equals(nightlyIcon);
  if (isNightlyVersion(version) && !wearsNightly) {
    throw new Error(`Nightly package ${version} was built without the nightly icon`);
  }
  if (!isNightlyVersion(version) && wearsNightly) {
    throw new Error(`Release package ${version} was built with the nightly icon`);
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  const version = packageVersion(ROOT);
  const swapped = applyNightlyIcon({ version });
  if (swapped.length) {
    console.log(`Nightly ${version}: using the nightly icon for ${swapped.length} files`);
    for (const dest of swapped) console.log(`  ${dest}`);
  } else {
    console.log(`Release ${version}: keeping the release icon`);
  }
}
